select run_date,count(*) supplier_rows,sum(case when has_missing_product_id then 1 else 0 end) missing_product_id_rows,sum(case when has_missing_currency then 1 else 0 end) missing_currency_rows,sum(case when has_invalid_price then 1 else 0 end) invalid_price_rows,sum(case when has_negative_price then 1 else 0 end) negative_price_rows,sum(case when has_unknown_stock_status then 1 else 0 end) unknown_stock_status_rows,sum(case when has_missing_valid_from then 1 else 0 end) missing_valid_from_rows,sum(case when has_invalid_valid_from then 1 else 0 end) invalid_valid_from_rows,sum(case when has_invalid_last_updated_at then 1 else 0 end) invalid_last_updated_at_rows,sum(case when is_duplicate_business_key then 1 else 0 end) duplicate_business_key_rows,max(ingested_at) latest_ingested_at from {{ ref('stg_supplier_product_updates') }} group by 1
